public static String check(Object got, Object expected) {
    String g = String.valueOf(got).trim();
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

exercise.mainCode:
System.out.println("סעיף א, בדיקה 1 (הדוגמה — המשקל עוצר): " + check(boardCount(new int[] { 80, 95, 70, 110, 85, 90, 75, 60 }), 6));
System.out.println("סעיף א, בדיקה 2 (10 אנשים עוצרים): " + check(boardCount(new int[] { 50, 50, 50, 50, 50, 50, 50, 50, 50, 50, 50 }), 10));
System.out.println("סעיף א, בדיקה 3 (600 בדיוק — מותר): " + check(boardCount(new int[] { 100, 100, 100, 100, 100, 100, 40 }), 6));
System.out.println("סעיף א, בדיקה 4 (מי שאחרי — לא עולה, גם אם קל): " + check(boardCount(new int[] { 300, 250, 90, 20 }), 2));
System.out.println("סעיף א, בדיקה 5 (התור נגמר): " + check(boardCount(new int[] { 70, 80 }), 2));

